"""Readable, interactive delivery of the four source-based organization studies."""
from pathlib import Path
import json,html

ROOT=Path(__file__).resolve().parents[1]/'reports/氯硫框架具体化/paper-maps-20261104'
LABELS={
 'qin2020':['硫酸盐反应与脱钙引起膨胀和弱化','反应—传输—损伤模型已能计算膨胀','钙溶出与温度会改变膨胀预测','耦合溶出和温度，对照两组膨胀试验'],
 'meng2024':['氯硫共同侵蚀影响混凝土服役寿命','氯侵入、钢筋去钝化与保护层开裂','硫酸盐改变水化相、结合氯与孔隙','盐浓度、材料和评价量改变侵蚀表现','已有模型怎样连接离子传输与结合','电作用是否改变氯硫竞争结合强度','交叉比较单盐/复盐与电作用开关'],
 'bae2025':['海水离子侵入伴随相变与孔隙演化','多离子迁移偏离经典Fick描述','孔径、AFm氯取代和静电作用影响离子剖面','反应传输迭代成本与海水试验误差','热力学相态计算与Bayesian参数估计'],
 'goswami2022':['初始缺陷与载荷变化需要多组裂纹模拟','裂纹路径对缺陷和材料波动敏感','变分PINN更换裂纹与载荷后仍需训练','由裂纹能量历史预测位移和损伤场','拉伸与剪切检验未训练裂纹和加载步'],
}
PAPERS=[]
for key in ['qin2020','meng2024','bae2025','goswami2022']:
    value=json.loads((ROOT/key/'content-map.json').read_text(encoding='utf8'));value['key']=key
    for n,label in zip(value['intro_nodes'],LABELS[key]):n['short_label']=label
    PAPERS.append(value)
comparison=(ROOT/'四篇内容组织比较.md').read_text(encoding='utf8')
body=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>四篇论文的内容组织图谱</title>
<style>
:root{color-scheme:light;font-family:"Microsoft YaHei UI","PingFang SC",sans-serif;color:#242a2b;background:#f4f5f2;line-height:1.7}*{box-sizing:border-box}body{margin:0}button{font:inherit;cursor:pointer}header{padding:32px 5vw 24px;border-bottom:1px solid #d8ded9;background:#fff}header p{max-width:920px;margin:9px 0;color:#55605d}h1{font-size:29px;line-height:1.4;margin:0}h2{font-size:21px;margin:0 0 12px}h3{font-size:17px;margin:0 0 10px}nav{display:flex;gap:8px;flex-wrap:wrap;margin-top:20px}nav button,.tab{border:1px solid #cbd4ce;border-radius:7px;background:#fff;padding:8px 14px;color:#34423b}nav button.active{background:#14594a;border-color:#14594a;color:white}main{max-width:1420px;margin:26px auto;padding:0 24px}.paper-title{font-family:Georgia,serif;font-size:23px;line-height:1.4;max-width:1050px}.meta{font-size:13px;color:#64706b}.lead{font-size:17px;max-width:1120px}.card{background:white;border:1px solid #d8ded9;border-radius:10px;padding:23px;margin:20px 0}.diagram{display:flex;gap:18px;overflow:auto;padding:12px 3px 22px;align-items:stretch}.step{flex:0 0 185px;position:relative;border:1px solid #c8d3ce;background:#fafcf9;border-radius:8px;padding:14px;text-align:left;line-height:1.5;color:#263b33}.step:not(:last-child):after{content:'→';position:absolute;right:-17px;top:45%;color:#54796c}.step.active{border:2px solid #14594a;background:#ecf6ee;padding:13px}.step small{display:block;color:#697b71;font-size:12px;margin-bottom:8px}.step strong{font-size:15px}.detail-grid{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:25px}.label{font-size:12px;color:#687a70;letter-spacing:.05em;margin:0 0 3px}.detail-grid p{margin:0 0 18px}.question{border-left:3px solid #b17f44;padding-left:15px;background:#fff9ef}.edges article{padding:17px 0;border-top:1px solid #e1e6e1}.edges article:first-child{border:0}.edges p{margin:7px 0}summary{cursor:pointer;color:#245b48}details{margin:18px 0}details p{font-size:14px;color:#53645c}table{border-collapse:collapse;width:100%;font-size:14px}th,td{border-bottom:1px solid #dfe5df;padding:13px 12px;vertical-align:top;text-align:left}th{color:#446150;background:#f1f5ef;width:18%}.route{border-top:1px solid #d7e0d8;padding:19px 0}.route:first-child{border:0}.route h3{color:#225e4a}.route .scope{font-size:13px;color:#756248}.comparison{max-width:960px;margin:auto}.comparison p{margin:19px 0}.borrow{display:grid;grid-template-columns:1fr 1fr;gap:14px}.borrow article{background:#f4f7f0;padding:15px;border-radius:6px}.borrow p{font-size:14px;margin:5px 0}a{color:#14594a}footer{padding:26px 5vw;color:#64716b;font-size:13px}@media(max-width:780px){header{padding:23px}h1{font-size:24px}main{padding:0 14px}.card{padding:18px}.detail-grid,.borrow{grid-template-columns:1fr}.paper-title{font-size:20px}th{width:27%}table{font-size:13px}}
</style><header><div class="meta">真实论文阅读 · 内容组织与承诺兑现</div><h1>四篇论文怎样建立连续论证</h1><p>从作者要回答的具体问题出发，逐段查看读者新增了什么认识、下一段为何进入，再追踪方法、比较结果与结论。点击段落卡片可展开细节。</p><nav id="nav"></nav></header><main id="main"></main><footer>摘要全文与逐节内容图谱在工作台“文献 → 内容图谱”中生成。此页交付四篇已人工连读论文的组织拆解；阅读版本和证据范围分别列明，未将论文报告的结果当成独立复现。</footer>
<script id="data" type="application/json">__DATA__</script><script>
const papers=JSON.parse(document.querySelector('#data').textContent),main=document.querySelector('#main'),nav=document.querySelector('#nav');
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n};
const add=(parent,tag,text,cls)=>{const n=el(tag,text,cls);parent.append(n);return n};
let selected=0,paragraph=0;
function field(parent,label,text){if(!text)return;add(parent,'div',label,'label');add(parent,'p',typeof text==='string'?text:JSON.stringify(text))}
function render(){[...nav.children].forEach((b,i)=>b.classList.toggle('active',selected===i));main.replaceChildren();if(selected===4){const s=add(main,'article',undefined,'card comparison');for(const p of __COMPARISON__.split(/\n\s*\n/)){add(s,p.startsWith('# ')?'h2':'p',p.replace(/^# /,'').replace(/\[([^\]]+)\]\([^)]*\)/g,'$1'))}return}
 const p=papers[selected];add(main,'div',p.title,'paper-title');const doi=add(main,'a','DOI '+p.doi,'meta');doi.href='https://doi.org/'+p.doi;doi.target='_blank';add(main,'p',p.author_question,'lead');const version=add(main,'details');add(version,'summary','实际阅读版本与范围');add(version,'p',p.read_version);add(version,'p',p.read_scope);
 const funnel=add(main,'section',undefined,'card');add(funnel,'h2','从哪个任务，收窄到哪个问题');const table=add(funnel,'table');for(const [k,label] of [['broad_need','预测需要'],['consequential_difficulty','影响预测的困难'],['turning_judgment','收窄的关键判断'],['precise_question','具体研究问题'],['response','本文怎样回应']]){const row=add(table,'tr');add(row,'th',label);add(row,'td',p.funnel[k]||'原记录未提供')}
 const intro=add(main,'section',undefined,'card');add(intro,'h2','引言段落与内容联系');add(intro,'p',p.opening_strategy);const diagram=add(intro,'div',undefined,'diagram');p.intro_nodes.forEach((node,i)=>{const b=add(diagram,'button',undefined,'step'+(i===paragraph?' active':''));add(b,'small',node.id+' · PDF p.'+node.pages.join('、'));add(b,'strong',node.short_label||node.role);b.onclick=()=>{paragraph=i;render()}});const node=p.intro_nodes[paragraph]||p.intro_nodes[0];const grid=add(intro,'div',undefined,'detail-grid'),left=add(grid,'div'),right=add(grid,'div');field(left,node.id+' 具体内容',node.content);field(left,'为什么放在这里',node.why_here);field(right,'这一段之前，读者知道什么',node.reader_before);field(right,'这一段增加的认识',node.reader_after);field(right,'留给下一段的问题',node.next_question);if(node.locator)field(left,'原文定位',node.locator);
 const edges=add(main,'section',undefined,'card edges');add(edges,'h2','段与段为何相接');for(const edge of p.intro_edges){const a=add(edges,'article');add(a,'h3',edge.from+' → '+edge.to+' · '+edge.relation);add(a,'p',edge.reason);if(edge.missing_if_removed){const box=add(a,'div',undefined,'question');field(box,'删去前段会怎样',edge.missing_if_removed)}}
 const routes=add(main,'section',undefined,'card');add(routes,'h2','引言提出的问题，后文怎样回答');for(const route of p.evidence_routes){const a=add(routes,'article',undefined,'route');add(a,'h3',route.promise);for(const [k,label] of [['method','方法选择'],['results','结果与比较'],['conclusion','结论收回什么']])field(a,label,route[k]);add(a,'p',route.locators,'meta');add(a,'p',route.scope,'scope')}
 const learning=add(main,'section',undefined,'card');add(learning,'h2','哪些组织关系可以借鉴');const boxes=add(learning,'div',undefined,'borrow');for(const b of p.borrowing){const a=add(boxes,'article');field(a,'原文怎样推进',b.source_move);field(a,'可迁移的关系',b.transfer);field(a,'与我们主线的关系',b.to_our_paper);field(a,'保留原例的适用范围',b.do_not_copy)}add(learning,'p',p.judgment);const file=add(learning,'a','阅读这一篇的完整分析');file.href=p.key+'/analysis.md';
}
papers.forEach((p,i)=>{const b=add(nav,'button',['Qin 2020','Meng 2024','Bae 2025','Goswami 预印本'][i]);b.onclick=()=>{selected=i;paragraph=0;render()}});const all=add(nav,'button','跨文比较与本稿建议');all.onclick=()=>{selected=4;render()};render();
</script></html>'''
body=body.replace('__DATA__',json.dumps(PAPERS,ensure_ascii=False).replace('<','\\u003c'))
body=body.replace('__COMPARISON__',json.dumps(comparison,ensure_ascii=False).replace('<','\\u003c'))
target=ROOT/'四篇论文内容图谱.html';target.write_text(body,encoding='utf8');print(target)
